// src/components/ROI/tabs/ProjectStatusTab.js
import React, { useState } from "react";
import { useOutletContext } from "react-router-dom";

export default function ProjectStatusTab() {
  const { intakeNumber, projectDetails } = useOutletContext?.() || {};

  // --- Compact UI helpers ---
  const labelCls = "text-sm text-gray-700";
  const inputCls = "border rounded px-2 py-1 text-sm";
  const selectCls = "border rounded px-2 py-1 text-sm";
  const areaCls = "border rounded px-2 py-1 text-sm";
  const sectionWrap = "border rounded-lg p-3 mb-3 bg-white";
  const sectionTitle =
    "tab-section tab-section-yellow !bg-yellow-50 !text-gray-800 !py-2 !px-3 !rounded mb-2";
  const grid2 = "grid grid-cols-1 md:grid-cols-2 gap-3";
  const grid3 = "grid grid-cols-1 md:grid-cols-3 gap-3";

  // --- Local state (you’ll wire backend later) ---
  const [details, setDetails] = useState({
    deliveryModel: "",
    timelinesAvailable: "",
    projectCurrentStatus: "",
  });

  const [stakeholders, setStakeholders] = useState({
    qaManager: "",
    functionalQeLead: "",
    funcSme: "",
    automationLeadOrQeLead: "",
    offshoreLead: "",
    fteOrAutomationArchitect: "",
    itPm: "",
  });

  const [dates, setDates] = useState({
    autoStartDate: "",
    autoEndDate: "",
    implementationDate: "",
  });

  const [estimation, setEstimation] = useState({
    estimateDueDate: "",
    estimateSubmittedOn: "",
    estimateStatusOrOOS: "",
    assignedToOrDoneBy: "",
    estimateReviewedBy: "",
    funcAutomation: "",
    reasonIfOOSorNoNew: "",
    qaCostWithoutAuto: "",
    qaCostWithAuto: "",
    targetedMinSavings: "",
  });

  const [automationStatus, setAutomationStatus] = useState({
    currentStatus: "",
    comments: "",
  });

  const [deliverables, setDeliverables] = useState({
    testPlanLTW: false,
    qaChecklistFollowed: false,
    tcUpdateInALMConfluence: false,
    gitUpdate: false,
    dsr: false,
    leSentToPMMonthly: false,
    masterRegUpdatedALM: false,
    masterDashboardUpdated: false,
    releaseHandover: false,
    projectClosureReport: false,
    roiRealizedIn: "",
    noROIReason: "",
    qeTransformed: false,
    shiftLeftFollowed: false,
  });

  const [initiatives, setInitiatives] = useState({
    conformiq: false,
    genAI_PS: false,
    ddgs_soa3: false,
    e2e: false,
    envoyAPI: false,
    qeDevops: false,
    excalibur_phase1: false,
    accessibility: false,
    mmtg_phase2: false,
    mmtgTDM: false,
    classTDM: false,
  });

  const onSave = () => {
    // TODO: hook up API
    console.log("Save Project Status", {
      intakeNumber,
      details,
      stakeholders,
      dates,
      estimation,
      automationStatus,
      deliverables,
      initiatives,
    });
  };

  // small field builder
  const Text = ({ label, value, onChange, placeholder, type = "text" }) => (
    <div className="flex flex-col">
      <span className={labelCls}>{label}</span>
      <input
        className={inputCls}
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
      />
    </div>
  );

  const Select = ({ label, value, onChange, options }) => (
    <div className="flex flex-col">
      <span className={labelCls}>{label}</span>
      <select
        className={selectCls}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      >
        <option value="">-- Select --</option>
        {options.map((o) => (
          <option key={o} value={o}>
            {o}
          </option>
        ))}
      </select>
    </div>
  );

  const Area = ({ label, value, onChange, placeholder }) => (
    <div className="flex flex-col md:col-span-2">
      <span className={labelCls}>{label}</span>
      <textarea
        className={areaCls}
        rows={3}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
      />
    </div>
  );

  const Check = ({ label, value, onChange }) => (
    <label className="inline-flex items-center gap-2 text-sm">
      <input
        type="checkbox"
        checked={value}
        onChange={(e) => onChange(e.target.checked)}
      />
      <span className="text-gray-700">{label}</span>
    </label>
  );

  return (
    <div className="tab-wrap">
      {/* Save top bar */}
      <div className="flex justify-end mb-3">
        <button className="btn-red" onClick={onSave}>
          &lt;Save&gt;
        </button>
      </div>

      {/* 1) Project Details */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Details</div>
        <div className={grid3}>
          <Select
            label="Delivery model"
            value={details.deliveryModel}
            onChange={(v) =>
              setDetails((s) => ({ ...s, deliveryModel: v }))
            }
            options={["Agile", "Waterfall", "Hybrid"]}
          />
          <Select
            label="Project Timelines Available ?"
            value={details.timelinesAvailable}
            onChange={(v) =>
              setDetails((s) => ({ ...s, timelinesAvailable: v }))
            }
            options={["Yes", "No", "Partial"]}
          />
          <Select
            label="Project Current Status"
            value={details.projectCurrentStatus}
            onChange={(v) =>
              setDetails((s) => ({ ...s, projectCurrentStatus: v }))
            }
            options={[
              "Initiated",
              "Discovery",
              "In Progress",
              "UAT",
              "Ready for Prod",
              "Closed",
              "On Hold",
            ]}
          />
        </div>
      </div>

      {/* 2) Project Stakeholders */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Stakeholders</div>
        <div className={grid3}>
          <Text
            label="QA Manager"
            value={stakeholders.qaManager}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, qaManager: v }))
            }
            placeholder="Name"
          />
          <Text
            label="Functional_qe_lead"
            value={stakeholders.functionalQeLead}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, functionalQeLead: v }))
            }
            placeholder="Name"
          />
          <Text
            label="Func. SME"
            value={stakeholders.funcSme}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, funcSme: v }))
            }
            placeholder="Name"
          />
          <Text
            label="Automation Lead (old) / QE lead (new)"
            value={stakeholders.automationLeadOrQeLead}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, automationLeadOrQeLead: v }))
            }
            placeholder="Name"
          />
          <Text
            label="Offshore Lead Resource"
            value={stakeholders.offshoreLead}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, offshoreLead: v }))
            }
            placeholder="Name"
          />
          <Text
            label="FTE (old) / Automation Architect (new)"
            value={stakeholders.fteOrAutomationArchitect}
            onChange={(v) =>
              setStakeholders((s) => ({
                ...s,
                fteOrAutomationArchitect: v,
              }))
            }
            placeholder="Name"
          />
          <Text
            label="IT PM"
            value={stakeholders.itPm}
            onChange={(v) =>
              setStakeholders((s) => ({ ...s, itPm: v }))
            }
            placeholder="Name"
          />
        </div>
      </div>

      {/* 3) Project Dates */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Project Dates</div>
        <div className={grid3}>
          <Text
            label="Auto. Work Start Date"
            type="date"
            value={dates.autoStartDate}
            onChange={(v) =>
              setDates((s) => ({ ...s, autoStartDate: v }))
            }
          />
          <Text
            label="Auto. Work End Date"
            type="date"
            value={dates.autoEndDate}
            onChange={(v) =>
              setDates((s) => ({ ...s, autoEndDate: v }))
            }
          />
          <Text
            label="Implementation Date"
            type="date"
            value={dates.implementationDate}
            onChange={(v) =>
              setDates((s) => ({ ...s, implementationDate: v }))
            }
          />
        </div>
      </div>

      {/* 4) Automation Estimation */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Automation Estimation</div>
        <div className={grid3}>
          <Text
            label="Estimate Due Date"
            type="date"
            value={estimation.estimateDueDate}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateDueDate: v }))
            }
          />
          <Text
            label="Estimate Submitted On"
            type="date"
            value={estimation.estimateSubmittedOn}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateSubmittedOn: v }))
            }
          />
          <Select
            label="Estimate Status / OOS"
            value={estimation.estimateStatusOrOOS}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateStatusOrOOS: v }))
            }
            options={[
              "Planned",
              "In Progress",
              "Submitted",
              "Approved",
              "Rejected",
              "Out of Scope",
            ]}
          />
          <Text
            label="Assigned to / Estimate Done by"
            value={estimation.assignedToOrDoneBy}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, assignedToOrDoneBy: v }))
            }
            placeholder="Name"
          />
          <Text
            label="Estimate Reviewed By"
            value={estimation.estimateReviewedBy}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, estimateReviewedBy: v }))
            }
            placeholder="Name"
          />
          <Select
            label="Func. Automation"
            value={estimation.funcAutomation}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, funcAutomation: v }))
            }
            options={["Yes", "No", "Partial"]}
          />
          <Area
            label="Reason if OOS / No new Automation"
            value={estimation.reasonIfOOSorNoNew}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, reasonIfOOSorNoNew: v }))
            }
            placeholder="Enter reason"
          />
          <Text
            label="Total QA Cost (Without Automation)"
            type="number"
            value={estimation.qaCostWithoutAuto}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, qaCostWithoutAuto: v }))
            }
            placeholder="0"
          />
          <Text
            label="Total QA Cost (With Automation)"
            type="number"
            value={estimation.qaCostWithAuto}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, qaCostWithAuto: v }))
            }
            placeholder="0"
          />
          <Text
            label="Targeted Min. Savings"
            type="number"
            value={estimation.targetedMinSavings}
            onChange={(v) =>
              setEstimation((s) => ({ ...s, targetedMinSavings: v }))
            }
            placeholder="0"
          />
        </div>
      </div>

      {/* 5) Automation Status */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Automation Status</div>
        <div className={grid2}>
          <Select
            label="Current Automation Status"
            value={automationStatus.currentStatus}
            onChange={(v) =>
              setAutomationStatus((s) => ({ ...s, currentStatus: v }))
            }
            options={[
              "Not Started",
              "In Progress",
              "Blocked",
              "Completed",
              "De-scoped",
            ]}
          />
          <Area
            label="Comments"
            value={automationStatus.comments}
            onChange={(v) =>
              setAutomationStatus((s) => ({ ...s, comments: v }))
            }
            placeholder="Notes, risks, blockers..."
          />
        </div>
      </div>

      {/* 6) QE Deliverables */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>QE Deliverables</div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
          <Check
            label="Automation Test Plan / LTW"
            value={deliverables.testPlanLTW}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, testPlanLTW: v }))
            }
          />
          <Check
            label="QA Checklist followed"
            value={deliverables.qaChecklistFollowed}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, qaChecklistFollowed: v }))
            }
          />
          <Check
            label="Test Case update in ALM/confluence"
            value={deliverables.tcUpdateInALMConfluence}
            onChange={(v) =>
              setDeliverables((s) => ({
                ...s,
                tcUpdateInALMConfluence: v,
              }))
            }
          />
          <Check
            label="GIT Update"
            value={deliverables.gitUpdate}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, gitUpdate: v }))
            }
          />
          <Check
            label="DSR"
            value={deliverables.dsr}
            onChange={(v) => setDeliverables((s) => ({ ...s, dsr: v }))}
          />
          <Check
            label="LE Sent to PM (Monthly Once)"
            value={deliverables.leSentToPMMonthly}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, leSentToPMMonthly: v }))
            }
          />
          <Check
            label="Master Regression Updated in ALM Library"
            value={deliverables.masterRegUpdatedALM}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, masterRegUpdatedALM: v }))
            }
          />
          <Check
            label="Master Dashboard Updated"
            value={deliverables.masterDashboardUpdated}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, masterDashboardUpdated: v }))
            }
          />
          <Check
            label="Release Handover"
            value={deliverables.releaseHandover}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, releaseHandover: v }))
            }
          />
          <Check
            label="Project Closure Report"
            value={deliverables.projectClosureReport}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, projectClosureReport: v }))
            }
          />
          <Text
            label="ROI Realized in"
            value={deliverables.roiRealizedIn}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, roiRealizedIn: v }))
            }
            placeholder="e.g., Prod month/year"
          />
          <Text
            label="No ROI Reason"
            value={deliverables.noROIReason}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, noROIReason: v }))
            }
            placeholder="Reason"
          />
          <Check
            label="QE Transformed"
            value={deliverables.qeTransformed}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, qeTransformed: v }))
            }
          />
          <Check
            label="Shift Left followed"
            value={deliverables.shiftLeftFollowed}
            onChange={(v) =>
              setDeliverables((s) => ({ ...s, shiftLeftFollowed: v }))
            }
          />
        </div>
      </div>

      {/* 7) Initiatives Planned Usage */}
      <div className={sectionWrap}>
        <div className={sectionTitle}>Initiatives Planned Usage</div>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
          <Check
            label="Conformiq"
            value={initiatives.conformiq}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, conformiq: v }))
            }
          />
          <Check
            label="GenAI_PS"
            value={initiatives.genAI_PS}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, genAI_PS: v }))
            }
          />
          <Check
            label="DDGS_SOA3"
            value={initiatives.ddgs_soa3}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, ddgs_soa3: v }))
            }
          />
          <Check
            label="E2E"
            value={initiatives.e2e}
            onChange={(v) => setInitiatives((s) => ({ ...s, e2e: v }))}
          />
          <Check
            label="EnvoyAPI"
            value={initiatives.envoyAPI}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, envoyAPI: v }))
            }
          />
          <Check
            label="QEDevops"
            value={initiatives.qeDevops}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, qeDevops: v }))
            }
          />
          <Check
            label="Excalibur_phase1"
            value={initiatives.excalibur_phase1}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, excalibur_phase1: v }))
            }
          />
          <Check
            label="Accessibility"
            value={initiatives.accessibility}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, accessibility: v }))
            }
          />
          <Check
            label="mMTG_Phase2"
            value={initiatives.mmtg_phase2}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, mmtg_phase2: v }))
            }
          />
          <Check
            label="mmtg TDM"
            value={initiatives.mmtgTDM}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, mmtgTDM: v }))
            }
          />
          <Check
            label="Class TDM"
            value={initiatives.classTDM}
            onChange={(v) =>
              setInitiatives((s) => ({ ...s, classTDM: v }))
            }
          />
        </div>
      </div>
    </div>
  );
}
